private typealias E = EvidenceSeed

/// Follow-up trials for the batch AX everyday-crime stories.
extension FollowUpCases {
    static let batchAX: [CaseTemplate] = [scaleRecheck, windowDashAgain, bookLiftAgain, steepleAgain, mailboxAgain2, signsAgain, eggsAgain, pumpkinsAgain, flowersAgain, woodAgain, tillAgain2, cartsAgain, bowlingAgain, tabAgain, tiresAgain, mowAgain, formulaAgain, perfumeAgain, pizzaAgain, shutoffAgain, lockedAgain, towAgain, bassAgain, blowerAgain, cartShoveAgain, gestureAgain, shedPaintAgain, pepperAgain, leafAgain, bikeAgain, landfillAgain, towerAgain, playgroundAgain, tailgateAgain, expiredAgain, stunAgain, voicemailAgain, trailerAgain, citationsAgain, permitAgain, gymBreakAgain, bikeFleeAgain2, cardSwapAgain, passwordAgain, permitFeeAgain, chargerAgain, lockerAgain2, trailerLate, hookupAgain, hayAgain, coversAgain, signsAgain2, sitterAgain, sitterCash, treasurerThird, ebikeAgain, phoneAgain2, bootsAgain, pastryAgain, liquorAgain2, caseAgain, atmAgain, wrongWayAgain, lobbyAgain, bannedAgain, burnoutsAgain, generatorAgain, paintballAgain, snowballAgain, sprinklerAgain, trailShoveAgain, fakeBillsAgain, tiresCheckAgain, checkbookAgain, fareAgain, prizeAgain, bingoAgain, horseAgain, depositAgain, growAgain, sitterRepeat, lightsAgain, fundAgain, railTagAgain, freightAgain, hoodAgain, tiresLetDown, eggsWindowAgain, kickAgain, shuttersAgain, fenceAgain, bellAgain, pranksAgain, robberyHoaxAgain, hoaxAgain, stolenCarAgain, nameAgain, hidesAgain, needlesAgain, sleepAgain]

    static let scaleRecheck = SmallCases.make(
        key: "story.followup.scaleRecheck",
        category: .whiteCollar,
        headlines: ["Vendor From Rigged Scale Case Sells at Another Market"],
        law: "falsePretenses",
        spec: "Obtained $60 from {V}, a market shopper, by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sold produce at a different market, and an inspector found the scale reading 9 percent heavy.",
        state: [E(.document, 3, "Inspector Report", "The scale reads 9 percent heavy.")],
        defense: [E(.statement, 1, "New Scale", "{DL} says the scale was new.")],
        role: "Market inspector",
        exam: [.direct("What is your job?", "\"I'm a county market inspector, and I check scales, pumps, and measures at farmers markets and roadside stands.\""), .direct("Where did you inspect {DL}?", "\"At a weekend market in a different part of the county from where {DL} was inspected before.\""), .direct("What did you find?", "\"The produce scale read nine percent heavy, so customers were charged for more weight than they received.\""), .direct("How do you test a scale?", "\"I place certified test weights on it and compare the readings. This one was off at every weight I tried.\""), .direct("What did one customer lose?", "\"A shopper paid sixty dollars for a purchase that should have cost about fifty-five, based on the error.\""), .direct("What did {DL} say?", "\"{D.He} said the scale was new and that {D.he} trusted the reading without testing it.\""), .cross("A new scale can be defective?", "\"It can, which is why a seller must have it tested before use.\""), .cross("The error ran in {DL}'s favor?", "\"Yes, it overstated the weight, so every customer paid more.\""), .cross("You found no hidden devices?", "\"No tampering that I could see. The error could be a calibration fault.\""), .cross("{DL} cooperated with your inspection?", "\"{D.He} did, and {D.he} took the scale out of service when I asked.\""), .cross("Other sellers had faulty scales that day?", "\"One other had a small error, but nothing near nine percent.\"")],
        theory: ("{D} shorted shoppers again.", "A bad new scale."),
        allocution: "\"I know how it looks, coming back here after the last time. But that scale was brand new, and I bought it a week before the market opened. I never put anything under the platform, and I would not know how. I'd ask the court to look at where that scale came from before deciding I cheated those shoppers.\"",
        truths: ("A magnet was under the platform again.", "The scale came from a store that recalled it."),
        defendant: [.direct("Where did you buy the scale?", "\"I bought it from a farm supply store about a month before. It came with a sticker saying it was calibrated.\""), .direct("Did you test it?", "\"I put a few known weights on it when I got it and it looked fine. I didn't check it again after that.\""), .direct("Did you know it read heavy?", "\"No. I never noticed, because customers rarely complained and I assumed the numbers were right.\""), .direct("What did you do when the inspector told you?", "\"I shut the scale down at once and refunded the shopper who had been overcharged.\""), .direct("Did you mean to overcharge anyone?", "\"No. I'd lose my regulars if I cheated them, and I need this market to earn a living.\""), .direct("What will you do now?", "\"I'll have the scale tested by a certified shop every season and keep the paperwork where inspectors can see it.\""), .cross("This is not your first weights-and-measures problem, is it?", "\"No, and that's why I should have been more careful about checking.\""), .cross("You relied on a sticker instead of testing?", "\"I did, and I see now that was not enough.\""), .cross("Nine percent is a large error, isn't it?", "\"It is, and I'm embarrassed I didn't catch it.\""), .cross("Customers paid more because of it?", "\"Some did, and I've offered refunds to anyone who remembers.\""), .cross("You'll keep records of each test?", "\"Yes, in a notebook on the table, dated and signed.\"")],
        openings: ("A county market inspector found a scale at {D}'s produce stand reading nine percent heavy at a market in a different part of the county from where {D} was inspected before, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say the scale was new and {D} trusted it to be accurate when {D.he} set up at the market. {D} did not know it was reading heavy, and had no reason to check."),
        closings: ("The inspector's report shows the scale nine percent heavy at a market stand, and after {PRIOR} {DL} knew scales must be checked before they are used to sell by weight.", "A new scale can be off out of the box, and {D} did not know. The State must prove {D} meant to short shoppers."),
        timeline: [(0, "The market opens."), (0, "An inspector tests the scale.")],
        identified: "Inspector Report",
        mood: .indifferent)

    static let windowDashAgain = SmallCases.make(
        key: "story.followup.windowDashAgain",
        category: .property,
        headlines: ["Drive-Thru Customer Leaves Without Paying Again"],
        law: "misdLarceny",
        spec: "Stole food valued at $48 belonging to {V}, a restaurant, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} drove off from another drive-thru without paying for a $48 order, and the plate matched.",
        state: [E(.video, 3, "Window Camera", "The car takes the bag and leaves.")],
        defense: [E(.statement, 1, "Card Trouble", "{DL} says the card failed.")],
        role: "Restaurant manager",
        exam: [.direct("What is your position?", "\"I'm the manager of a fast-food restaurant with a drive-thru window that serves most of our customers.\""), .direct("What happened that evening?", "\"A driver ordered forty-eight dollars of food, took the bag at the window, and drove off without paying.\""), .direct("What does the camera show?", "\"It shows a car at the window, a worker handing out the bag, and the car pulling away as the worker reaches for the payment.\""), .direct("How was the car identified?", "\"The plate is visible on the window camera, and it matched a car registered to {DL}.\""), .direct("What did you do?", "\"I called the sheriff's office and gave them the video, the order receipt, and the time.\""), .direct("What did {DL} say?", "\"{D.He} said {D.his} card failed at the window and that {D.he} meant to come back and pay.\""), .cross("Cards do fail sometimes?", "\"Yes, it happens, and we usually ask a customer to pull ahead and try again.\""), .cross("The worker was handing out the bag?", "\"Yes. The worker gave it before the payment went through, which our policy discourages.\""), .cross("{DL} never came back?", "\"Not that night or since. We have not seen {D.him} in the store.\""), .cross("The car is clearly on camera?", "\"Yes, and the plate is easy to read.\""), .cross("The loss is forty-eight dollars?", "\"That's the total of the order that was handed out, yes, including tax and the drinks.\"")],
        theory: ("{D} drove off without paying.", "A card failure."),
        allocution: "\"My card was declined at that window, and I panicked instead of saying so. I should have handed the bag back or gone inside and sorted it out with the manager. I did not mean to steal anybody's dinner. I'm sorry for the trouble I caused that restaurant and for the staff who had to chase it.\"",
        truths: ("The card was never run.", "The reader worked."),
        defendant: [.direct("Did you pay for the food?", "\"I tried. My card was declined at the window, and I told the worker I'd bring cash back.\""), .direct("Why did you drive away?", "\"The line behind me was long, and the worker had already handed me the bag. I figured I'd come back fast.\""), .direct("Did you go back?", "\"I meant to the next morning, but I got busy at work and then I was embarrassed about it.\""), .direct("Did you plan to take the food for free?", "\"No. If I'd planned that, I'd have used a different car or a different window.\""), .direct("What did the deputy ask you?", "\"{OFF.He} asked about the card, and I showed {OFF.him} the declined notice on my phone from that evening.\""), .direct("What would you tell the manager?", "\"I'm sorry. I'll pay forty-eight dollars right now and whatever else the court says.\""), .cross("This isn't the first time you left a drive-thru without paying, is it?", "\"No, and I know that's why this looks like a habit and not a mistake.\""), .cross("You had cash at home but not with you?", "\"I did, which is why I thought I could fix it later.\""), .cross("You didn't call the restaurant afterward?", "\"No, and I should have. That would have shown I meant to pay.\""), .cross("You're able to pay the order today?", "\"Yes, I have the money with me.\""), .cross("You'll pay before ordering in future?", "\"I will. I'll pay inside or not order.\"")],
        openings: ("The manager of a fast-food restaurant watched a driver order $48 of food, take the bag at the window, and drive off without paying, and the window camera shows the car and the plate matches {D}'s, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say {D}'s card failed at the window and {D} meant to come back and pay. {D} did not know the charge had not gone through."),
        closings: ("The camera shows the car take the bag and leave, the plate matches {D}'s, and after {PRIOR} {DL} knew what leaving without paying means.", "A card that fails at the window is a mistake, not a plan. The State must prove {D} meant to drive off with the order and had no intention of paying at the window."),
        timeline: [(0, "The order."), (0, "The car leaves.")],
        identified: "Window Camera",
        mood: .indifferent)

    static let bookLiftAgain = SmallCases.make(
        key: "story.followup.bookLiftAgain",
        category: .property,
        headlines: ["Library Reports More Rare Books Missing After Earlier Case"],
        law: "misdLarceny",
        spec: "Stole books valued at $300 belonging to {V}, a library, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, Two rare books vanished from another library after {D} visited, and a camera showed a tote bag.",
        state: [E(.video, 3, "Reading Room Camera", "{D} puts books in a tote bag.")],
        defense: [E(.statement, 1, "Borrowed", "{DL} says {D.he} meant to check them out.")],
        role: "Librarian",
        exam: [.direct("What is your position?", "\"I'm the librarian in charge of the rare-book room and reading room at our branch.\""), .direct("What went missing?", "\"Two rare books, a county history and an early survey, valued at about three hundred dollars together.\""), .direct("When did you notice?", "\"During our weekly inventory the next morning, when the shelf was missing two volumes.\""), .direct("What does the reading-room camera show?", "\"It shows {DL} at a table with the books, then putting them into a tote bag and leaving.\""), .direct("Did {DL} check them out?", "\"No. The system shows no checkout, and the books have security strips that were never disabled.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} meant to check them out and simply forgot to stop at the desk.\""), .cross("The security strip didn't alarm?", "\"The gate was out of service that week for repairs.\""), .cross("{DL} has a library card?", "\"Yes, a valid one, with no unpaid fines.\""), .cross("The books were returned?", "\"Yes, two days later, left in the book drop.\""), .cross("{DL} is a regular patron?", "\"{D.He} comes in often, and we have never had a problem before.\""), .cross("Rare books aren't normally checked out?", "\"They're not, which is why they're kept in the reading room.\"")],
        theory: ("{D} took books again.", "A forgotten checkout."),
        allocution: "\"Those books were going to be checked out, I promise you. I was late for work, I had them in my tote, and I walked out thinking about the clock instead of the desk. I love that library, and I would never sell its books. I'm sorry it looks like something worse, and I'm sorry for the worry it caused the staff.\"",
        truths: ("A pawn listing offered them.", "The desk was staffed."),
        defendant: [.direct("Why did you put the books in your bag?", "\"I wanted to study them at home. I thought I could check them out at the desk on my way out.\""), .direct("Why didn't you stop at the desk?", "\"A phone call came in as I reached the door, and I stepped outside to answer it without thinking.\""), .direct("What did you do with the books?", "\"I read them that night, and I brought them back to the book drop two days later.\""), .direct("Did you know they were rare?", "\"I knew they were kept in the reading room. I didn't know they couldn't be borrowed.\""), .direct("Did you mean to keep them?", "\"No. I'd never take history books I love. I just wasn't careful.\""), .direct("What would you tell the librarian?", "\"I'm sorry for the worry. I'll stay in the reading room from now on and pay whatever the library asks.\""), .cross("You've been in trouble at a library before, haven't you?", "\"Yes, and I should have been much more careful about the rules this time.\""), .cross("The camera shows you hiding the books in the bag?", "\"It shows me putting them in, and I understand why that looks bad.\""), .cross("You waited two days to return them?", "\"I did, and I should have brought them back that same night.\""), .cross("You didn't speak to anyone at the desk?", "\"No, and that's the mistake I keep thinking about.\""), .cross("You'll stay out of the rare-book room?", "\"Yes, unless a librarian is with me.\"")],
        openings: ("Two rare books, a county history and an early survey worth about $300 together, vanished from a library's rare-book room after {D} visited, and the reading room camera shows {D} put books in a tote bag, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} meant to check the books out and forgot, a mix-up and not a theft. {D} carried them openly."),
        closings: ("The camera shows {D} putting books in a tote bag, the books are gone, and after {PRIOR} {DL} knew what the reading room rules require.", "A forgotten checkout is a mistake, not a theft, and {D} carried the bag in plain view. The State must prove {D} meant to keep the books."),
        timeline: [(0, "The books go into the bag."), (1, "The shelf is found bare.")],
        identified: "Reading Room Camera",
        mood: .indifferent)

    static let steepleAgain = SmallCases.make(
        key: "story.followup.steepleAgain",
        category: .property,
        headlines: ["Another Church Painted After Earlier Case"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, a church, causing damage of $800, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, A second church's wall was painted overnight, and a camera showed {D}.",
        state: [E(.video, 3, "Neighbor Camera", "{D} carries cans.")],
        defense: [E(.statement, 1, "Walk", "{DL} says {D.he} was walking.")],
        role: "Church deacon",
        exam: [.direct("What is your role at the church?", "\"I'm a deacon, and I look after the building and grounds along with a few other volunteers.\""), .direct("What did you find?", "\"A long wall facing the road was painted over with black paint overnight, with words covering the stonework.\""), .direct("What was the damage?", "\"About eight hundred dollars to clean and repaint the wall and repair the stone.\""), .direct("What does the neighbor's camera show?", "\"It shows a person carrying cans along the road toward the church at night, and later leaving the same way.\""), .direct("Who is that person?", "\"The neighbor and I both think it's {DL}, from the walk and the clothes, though the face is hard to see.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was just out walking and carrying cans from a project at home.\""), .cross("The camera is far from the church?", "\"Yes, it's across the road and down a bit.\""), .cross("You didn't see the paint being applied?", "\"No. We found the wall the next morning.\""), .cross("{DL} has no history with your church?", "\"None that I know of. {D.He} isn't a member.\""), .cross("The cans on the video look ordinary?", "\"From that distance, yes. They could be paint or anything else.\""), .cross("No paint was found on {DL}?", "\"Deputies reported a few spots on {D.his} jacket, but nothing definite.\"")],
        theory: ("{D} painted a church again.", "A late-night walk."),
        allocution: "\"I was walking that night, and I will tell you again that I did not paint that church. I understand the camera and the cans in my garage make it look bad, and I can see why people are upset. But I have never had a reason to harm a church. I'd ask you to look at that camera build again.\"",
        truths: ("Paint matched cans in {DL}'s garage.", "The camera shows a different build."),
        defendant: [.direct("Were you near the church that night?", "\"I walked past it on my way home from a friend's house. I walk that road often.\""), .direct("What were you carrying?", "\"Two cans of stain from a deck project at home. I'd borrowed them from a friend.\""), .direct("Did you paint the wall?", "\"No. I never touched that church. I didn't even slow down.\""), .direct("How did paint get on your jacket?", "\"I had been staining my own deck earlier that day. The spots were already there.\""), .direct("What did you tell the deputy?", "\"I told {OFF.him} where I'd been and who I'd seen, and I showed {OFF.him} the deck.\""), .direct("What would you tell the deacon?", "\"I'm sorry the church was damaged. I wasn't part of it, and I hope you find who did it.\""), .cross("You've been charged with defacing property before, haven't you?", "\"Yes, and I'm trying to stay clear of anything like it. That's why I'm upset to be here.\""), .cross("The video shows someone with cans?", "\"It does, and I understand why that looks like me. It was me walking home, nothing more.\""), .cross("You didn't see anyone else on the road?", "\"No one, which is why I can't point to another person.\""), .cross("You walk that way often?", "\"Most evenings, which is why the neighbor knows my walk.\""), .cross("You'll let deputies check your deck?", "\"Yes, and the cans. They can test the stain against the church wall.\"")],
        openings: ("A long wall facing the road at a second church was painted over in black overnight, with words covering the stonework, and a neighbor's camera shows {D} carrying cans, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} was walking late at night and carrying cans for another reason. {D} did not paint the wall."),
        closings: ("The camera shows {D} with cans, the wall was painted overnight, and after {PRIOR} {DL} knew what a church wall means to a congregation.", "A man carrying cans on a late walk is not a painter, and a camera cannot show who painted a wall. The State must prove {D} painted the church wall, and not merely that {D} was nearby."),
        timeline: [(0, "1 a.m.: {DL} passes."), (1, "The wall is found.")],
        identified: "Neighbor Camera",
        mood: .indifferent)

    static let mailboxAgain2 = SmallCases.make(
        key: "story.followup.mailboxAgain2",
        category: .property,
        headlines: ["Plow Knocks Down Mailboxes Again"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, mailboxes, causing damage of $300, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} struck two mailboxes on another road and kept going.",
        state: [E(.document, 3, "Truck Log", "{D} drove that route.")],
        defense: [E(.statement, 1, "Whiteout", "{DL} says snow hid the boxes.")],
        role: "Resident",
        exam: [.direct("Where do you live?", "\"On a rural road with a row of mailboxes at the end of each driveway.\""), .direct("What happened to your mailbox?", "\"It was knocked flat in the night, and the post snapped off at the base.\""), .direct("Were others hit?", "\"Yes, my neighbor's was knocked down too, and both were about three hundred dollars together to replace.\""), .direct("What did you find on the road?", "\"Pieces of a plastic bumper cover and paint scrapes on the post, in white.\""), .direct("How was {DL} linked?", "\"A county truck log shows {DL} drove that route that night, and {D.his} truck is white.\""), .direct("What did {DL} say?", "\"{D.He} said snow was blowing and {D.he} couldn't see the boxes.\""), .cross("It was snowing that night?", "\"Yes, a steady snow with drifting at the edges of the road.\""), .cross("The boxes were close to the road?", "\"Close, though no more than usual for our area.\""), .cross("{DL} didn't stop?", "\"I didn't see {D.him} stop. We found the damage in the morning.\""), .cross("You didn't see the truck hit them?", "\"No one did. I was asleep.\""), .cross("Other trucks use that route?", "\"A few do, including school buses in the morning.\"")],
        theory: ("{D} hit boxes again.", "A whiteout."),
        allocution: "\"The roads were bad that night and I could barely see past the hood. I did not know I had struck anything, and I wouldn't have driven off if I had. I feel terrible that two families woke up to broken mailboxes. If I did this, it was a mistake of the weather and not of character, and I would gladly help repair them.\"",
        truths: ("Yellow paint was on the posts.", "The posts were buried in snow."),
        defendant: [.direct("Were you driving that road?", "\"Yes, I drive it as part of my route, usually plowing or sanding after a storm.\""), .direct("Did you hit the mailboxes?", "\"I felt something once or twice, but the snow was thick and I thought it was drifts or a stump.\""), .direct("Why didn't you stop?", "\"I couldn't see anything behind me in the snow. I didn't think I'd hit a mailbox.\""), .direct("Did you know you caused damage?", "\"Not until the deputy told me the next day. I'd have stopped if I'd known.\""), .direct("What did you do when you heard?", "\"I looked at my truck and found the scrape on my bumper, and I told the deputy about it.\""), .direct("What would you tell your neighbors?", "\"I'm sorry for the damage. I'll pay to replace both mailboxes.\""), .cross("You have been before this court for leaving a scene, haven't you?", "\"Yes, and I see why you question me. I'm telling you I didn't know this time.\""), .cross("You felt a bump and kept going?", "\"I did, and I should have stopped to look. I take that seriously.\""), .cross("You use the boxes as markers?", "\"Often, which makes it worse that I hit them.\""), .cross("Your truck has a scrape?", "\"It does, on the right side, and it matches the height of the posts.\""), .cross("You'll pay for the boxes?", "\"Yes, today if you want me to.\"")],
        openings: ("On a rural road, two mailboxes were knocked flat in the night, one with its post snapped at the base, and {D}'s truck log shows {D} drove that route, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say snow hid the boxes from the road, and {D} did not know {D.he} had hit them. A whiteout hides a lot."),
        closings: ("The truck log puts {D} on the road, two boxes were hit, and after {PRIOR} {DL} knew the route and the boxes.", "A driver in a whiteout may not know what {D.he} hit, and {D} did not mean to damage anything. The State must prove {D} knew."),
        timeline: [(0, "The plow passes."), (1, "The boxes are found.")],
        identified: "Truck Log",
        mood: .indifferent)

    static let signsAgain = SmallCases.make(
        key: "story.followup.signsAgain",
        category: .property,
        headlines: ["Campaign Signs Taken Again"],
        law: "misdLarceny",
        spec: "Stole yard signs valued at $150 belonging to {V}, a campaign, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, Another candidate's signs were pulled up overnight, and a camera showed {D}'s truck.",
        state: [E(.video, 3, "Doorbell Camera", "{D} loads signs.")],
        defense: [E(.statement, 1, "Trash", "{DL} says they were abandoned.")],
        role: "Campaign volunteer",
        exam: [.direct("What is your role in the campaign?", "\"I'm a volunteer who helps put up and check signs for our candidate in the local election.\""), .direct("What happened to the signs?", "\"About thirty signs along a county road were pulled out overnight, with the stakes left in the ground.\""), .direct("What was the loss?", "\"Roughly one hundred fifty dollars in printed signs, which we couldn't reuse.\""), .direct("What does the doorbell camera show?", "\"A truck stopping along the road, a person pulling up signs and loading them into the bed.\""), .direct("Whose truck is it?", "\"The plate is partly visible and matches a truck registered to {DL}.\""), .direct("What did {DL} say?", "\"{D.He} said the signs were abandoned on the roadside and that {D.he} thought they were trash.\""), .cross("The signs were on public right-of-way?", "\"Some were, and some were on private yards with permission.\""), .cross("Election signs are sometimes left behind?", "\"Sometimes, after an election, but this was weeks before voting.\""), .cross("{DL} supports another candidate?", "\"I believe so, since {D.his} yard has a rival's sign.\""), .cross("The signs were returned?", "\"No. They were found in a dumpster behind a store.\""), .cross("{DL} didn't try to hide the truck?", "\"The truck was in plain view of the camera.\"")],
        theory: ("{D} took signs again.", "Abandoned signs."),
        allocution: "\"I thought those signs were left on the roadside and loose, and I took them to the dump along with other trash I was hauling. I never meant to interfere with anybody's campaign. I understand the volunteers worked hard putting them up, and I'm truly sorry that I made their job harder in the last weeks.\"",
        truths: ("Signs were in {DL}'s shed.", "They had stakes."),
        defendant: [.direct("Why did you pull up the signs?", "\"I saw them leaning and mixed in with litter, and I thought someone had abandoned them.\""), .direct("Did you know whose they were?", "\"I could read the candidate's name, but I didn't think anyone cared that much about old signs.\""), .direct("What did you do with them?", "\"I loaded them into my truck and threw them away at a dumpster on my way home.\""), .direct("Did you support another candidate?", "\"I did, but I never meant to damage the other campaign. It wasn't about politics.\""), .direct("Did you know it was weeks before the election?", "\"I didn't think about that. I only thought of cleaning up the road.\""), .direct("What would you tell the campaign?", "\"I'm sorry for the loss. I'll pay for the signs and replace any that you tell me about.\""), .cross("You've been charged over campaign signs before, haven't you?", "\"Yes, and I should have left every sign alone for that reason.\""), .cross("Signs with stakes aren't litter, are they?", "\"No, and I admit I was careless about that.\""), .cross("You got rid of them in a dumpster?", "\"I did, and I wish I'd called someone first.\""), .cross("You support the other candidate?", "\"Yes, and I understand how that appears to the court. I should have known better.\""), .cross("You'll cover the cost?", "\"Yes, one hundred fifty dollars, or whatever the campaign can show it cost.\"")],
        openings: ("About thirty signs for another candidate were pulled out of the ground along a county road overnight, with the stakes left in place, and a doorbell camera shows {D}'s truck loading signs, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say the signs were abandoned and {D} picked them up as litter. {D} did not know they belonged to a candidate."),
        closings: ("The camera shows {D} loading signs into a truck, thirty were pulled overnight with the stakes left behind, and with {PRIOR} already on {D.his} record, {DL} knew exactly whose signs they were and what they stood for.", "Signs left along a road look abandoned, and {D} did not know otherwise. The State must prove {D} meant to take another candidate's signs."),
        timeline: [(0, "11 p.m.: the truck."), (1, "The volunteer sees empty lawns.")],
        identified: "Doorbell Camera",
        mood: .indifferent)

    static let eggsAgain = SmallCases.make(
