        role: "Car owner",
        exam: [.direct("Whose car was hit?", "\"Mine, a car I had parked on the street right outside my house overnight, where I always leave it.\""), .direct("What did you find in the morning?", "\"Dried egg across the windshield, hood, and doors, with bits of shell stuck in the paint along the edges.\""), .direct("What was the damage?", "\"About four hundred dollars to clean, buff, and repaint where the egg etched the clear coat.\""), .direct("What does the camera show?", "\"A neighbor's camera shows a figure on the sidewalk throwing eggs at several parked cars, including mine, one after another.\""), .direct("Who was it?", "\"The neighbor identified the figure as {DL}, who lives nearby, from the walk and the jacket.\""), .direct("What did {DL} say?", "\"{D.He} said it was a prank and that {D.he} meant no real harm.\""), .cross("It was dark when this happened?", "\"Yes, it was around eleven at night, but there is a streetlight close to where my car was parked.\""), .cross("Eggs wash off, don't they?", "\"Usually, but they sat overnight and etched the finish.\""), .cross("You weren't hurt?", "\"No, I wasn't hurt at all, and nothing on the car was broken, just dirty and etched.\""), .cross("Other cars were hit?", "\"At least three, down the same stretch of road.\""), .cross("{DL} apologized?", "\"{D.He} said sorry when a deputy spoke to {D.him}, but not to me.\"")],
        theory: ("{D} egged cars again.", "A prank."),
        allocution: "\"It was one egg, and it was a stupid thing to do. I was with friends, we were being childish, and I didn't think about someone having to scrub that car in the morning. Nobody was hurt, but that does not make it right. I'm sorry to the owner, and I'll pay for whatever it cost to clean.\"",
        truths: ("Eggshells were in the back seat.", "The eggs were old."),
        defendant: [.direct("Did you throw the eggs?", "\"Yes, I did. I was out with a couple of friends and we thought it would be funny.\""), .direct("Why did you do it?", "\"We were bored and I didn't think. I never imagined the damage it would cause.\""), .direct("Did you know the owner?", "\"I knew the cars belonged to neighbors, but I didn't pick any one in particular.\""), .direct("What happened after?", "\"I went home right away and felt bad about it. I heard the next day that someone filmed me.\""), .direct("What did you tell the deputy?", "\"I admitted it, and I said I'd pay for the cleaning and any damage to the paint.\""), .direct("What would you tell the car owner?", "\"I'm sorry for making a mess of your car. I'll pay the four hundred dollars and apologize in person.\""), .cross("You threw eggs at cars once before, didn't you?", "\"Yes, and I told myself I'd never do it again. I broke that promise.\""), .cross("You know eggs can harm paint?", "\"I do now. I didn't think about it that night.\""), .cross("Your friends were with you?", "\"They were, and I'm not blaming them. The decision was mine.\""), .cross("You aimed at parked cars on purpose?", "\"I did, and I can't explain it except to say it was a stupid choice.\""), .cross("You'll pay the full amount?", "\"Yes, and I can start with part of it today.\"")],
        openings: ("{V} parked outside {V.his} house overnight and woke to dried egg across the windshield, hood and doors, with shell stuck in the paint, and a neighbor's camera shows {D} throwing eggs, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say it was a prank and nothing more, with no intention of damaging anything. {D} meant it as a joke."),
        closings: ("The camera shows {D} throwing eggs, the car was covered across the windshield, hood and doors, and after {PRIOR} {DL} knew what dried egg does to paint and to a person's morning.", "A prank is not a crime unless damage is intended, and eggs wash off. The State must prove {D} meant to damage the car."),
        timeline: [(0, "The car cruises."), (1, "The paint is found damaged.")],
        identified: "Neighbor Camera",
        mood: .indifferent)

    static let pumpkinsAgain = SmallCases.make(
