        role: "Farm owner",
        exam: [.direct("What is your business?", "\"I run a farm stand where we sell pumpkins, gourds, and cider in the fall.\""), .direct("What was taken?", "\"About twenty large pumpkins from the pile near the road, worth around two hundred dollars.\""), .direct("When did you notice?", "\"At closing time, the pile looked much smaller than it had that afternoon.\""), .direct("What does the stand camera show?", "\"A van backed up to the pile, and a person loading pumpkins into the back before driving off.\""), .direct("Whose van is it?", "\"The plate is visible, and it matches a van registered to {DL}.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} put money in the honor box for the pumpkins.\""), .cross("You have an honor box?", "\"Yes, a metal box by the pile for customers who come when no one is there.\""), .cross("Was there money in the box that day?", "\"A small amount, but nowhere near the value of twenty pumpkins.\""), .cross("The stand is staffed all day?", "\"Not always. We step away to pick or restock.\""), .cross("Prices are posted?", "\"Yes, on a sign, with a price for each size.\""), .cross("The van left right after loading?", "\"It did, in the time it took the video to show it.\"")],
        theory: ("{D} took pumpkins again.", "Money in the box."),
        allocution: "\"I put money in that box, and I believed it was enough for the pumpkins I loaded. I can see now that I should have counted what I was taking and paid the posted price. I'm sorry to the family who runs that stand, because it's their living, and I would never want to cheat them out of it.\"",
        truths: ("The box held $5.", "{DL} resells them."),
        defendant: [.direct("Did you take pumpkins from the stand?", "\"Yes, I loaded a number of them for a fall display at a church event I was helping with.\""), .direct("Did you pay?", "\"I put money in the honor box, though I may not have paid enough for the number I took.\""), .direct("How much did you leave?", "\"I left forty dollars, which I thought was about right. I didn't count how many pumpkins I took.\""), .direct("Why didn't you talk to the owner?", "\"No one was at the stand, and the sign said to use the honor box.\""), .direct("Did you mean to cheat the farm?", "\"No. I'd have paid more if I'd counted. I was in a hurry and misjudged it.\""), .direct("What would you tell the owner?", "\"I'm sorry. I'll pay the difference today and bring the receipt for the church event.\""), .cross("You've been accused of taking from a stand before, haven't you?", "\"Yes, and I should have been extra careful to pay fully this time.\""), .cross("You didn't count the pumpkins?", "\"I didn't, and I understand that's a problem.\""), .cross("Forty dollars doesn't cover twenty pumpkins, does it?", "\"No, and I see that now. I'll make up the difference.\""), .cross("You drove away without leaving a note?", "\"I did, and a note would have helped. I should have written one.\""), .cross("You'll pay the remaining amount?", "\"Yes, one hundred sixty dollars, or whatever the owner says it should be.\"")],
        openings: ("About twenty large pumpkins from the pile near the road, worth around $200, were taken from a farm stand, and a stand camera shows {D}'s van loading them, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} paid by putting money in the box, as customers do at honor stands. {D} did not steal."),
        closings: ("The camera shows {D}'s van loading twenty pumpkins from the pile near the road, and after {PRIOR} {DL} knew what taking from a farm stand means to the family that grew them.", "An honor box is easy to miss on a camera, and {D} says {D.he} paid. The State must prove {D} did not."),
        timeline: [(0, "The van pulls in."), (1, "The owner counts the box.")],
        identified: "Stand Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let flowersAgain = SmallCases.make(
        key: "story.followup.flowersAgain",
        category: .property,
        headlines: ["Grave Flowers Missing at Second Cemetery"],
        law: "misdLarceny",
        spec: "Stole flower arrangements valued at $120 belonging to {V}, a cemetery visitor, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, A groundskeeper at another cemetery saw {D} loading arrangements into a trunk.",
        state: [E(.video, 3, "Groundskeeper Statement", "{D} loaded arrangements.")],
        defense: [E(.statement, 1, "Cleanup", "{DL} says {D.he} was clearing old flowers.")],
        role: "Groundskeeper",
        exam: [.direct("What is your job?", "\"I'm a groundskeeper at a cemetery, and I take care of the grounds, graves, and walks.\""), .direct("What did you see?", "\"I saw a person walking among the graves, picking up arrangements from several plots and carrying them to a car.\""), .direct("What kind of arrangements?", "\"Fresh and silk flowers that families had left, worth maybe a hundred twenty dollars in total.\""), .direct("What did the person do next?", "\"Put them into the trunk of a car at the side gate and drove away.\""), .direct("Who was it?", "\"I recognized {DL} from earlier in the day, when {D.he} asked me where the new graves were.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was clearing out old flowers to help keep the cemetery tidy.\""), .cross("Cemeteries do remove old flowers?", "\"We do, on a schedule, and families are told when.\""), .cross("Some of the arrangements were wilted?", "\"A few were, but most were fresh from that week.\""), .cross("You didn't stop {DL}?", "\"I called out, and {D.he} kept walking. I went to call the sheriff's office.\""), .cross("You didn't see {DL} keep the flowers?", "\"I saw them put in a trunk and the car leave.\""), .cross("{DL} was polite when you spoke earlier?", "\"Yes, {D.he} was courteous and asked for directions.\"")],
        theory: ("{D} took flowers again.", "A cleanup."),
        allocution: "\"I was clearing old arrangements the way the county asked me to, and I truly thought that was part of the job. I understand now that some of those flowers were fresh and left by families who cared about them. I'm sorry for the hurt that caused, especially to people visiting someone they miss. I'll be more careful about what is mine to move.\"",
        truths: ("The flowers were fresh.", "{DL} sold bouquets."),
        defendant: [.direct("Why did you take the flowers?", "\"I thought they were old and abandoned. A few were wilted, and I thought I was helping to tidy up.\""), .direct("Did anyone give you permission?", "\"No. I didn't ask the staff. I should have, and I see why it looks wrong.\""), .direct("What did you plan to do with them?", "\"I planned to throw them away at my house. I didn't intend to sell them or keep them.\""), .direct("Did you know families had left them?", "\"I knew they were put there by someone, but I thought they'd stayed too long.\""), .direct("What did you do when the groundskeeper called out?", "\"I kept walking because I was embarrassed. I didn't realize I was doing something so wrong.\""), .direct("What would you tell the families?", "\"I'm sorry for taking what you left for your loved ones. I'll never touch anything at a grave again.\""), .cross("You've been in court over cemetery items before, haven't you?", "\"Yes, and that's why this is hard to explain. I should have asked first.\""), .cross("You carried arrangements out of the gate?", "\"I did, and I'll never do that again.\""), .cross("You didn't tell anyone in the office?", "\"No. I should have gone there before touching anything.\""), .cross("Fresh flowers don't look abandoned, do they?", "\"Not all of them. I made a poor judgment.\""), .cross("You'll stay out of that cemetery?", "\"Yes, unless I'm paying respects, and I'll bring my own flowers.\"")],
        openings: ("A groundskeeper at another cemetery saw {D} walking among the graves, picking up arrangements from several plots and carrying them to a car, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} was clearing old flowers from the plots, which cemeteries do every week, and was not taking anything of value. {D} meant to help the grounds."),
        closings: ("The groundskeeper saw {D} take arrangements from several plots to a car, and after {PRIOR} {DL} knew what they mean to families.", "Clearing old flowers from a cemetery is a service, not a theft, and {D} meant no harm to any family. The State must prove {D} took what belonged to others and meant to keep it."),
        timeline: [(0, "{DL} walks the rows."), (1, "{V} finds a bare grave.")],
        identified: "Groundskeeper Statement",
        mood: .indifferent)

    static let woodAgain = SmallCases.make(
        key: "story.followup.woodAgain",
        category: .property,
        headlines: ["Firewood Taken Again From Roadside Seller"],
        law: "misdLarceny",
        spec: "Stole firewood valued at $200 belonging to {V}, a seller, on {DATE}.",
        ages: 18...60,
