        state: [E(.physical, 3, "Perfume Bottles", "Two tagged bottles.")],
        defense: [E(.statement, 1, "Sample", "{DL} says {D.he} forgot them.")],
        role: "Security officer",
        exam: [.direct("What is your job?", "\"I'm a security officer for a department store, and I watch the cosmetics and fragrance counters for losses.\""), .direct("What did you see?", "\"I saw {DL} pick up two bottles of perfume from a display and slip them into a coat pocket while looking toward the exit.\""), .direct("What happened next?", "\"{DL} walked past the registers without stopping and headed for the doors, so I stopped {D.him} outside the entrance.\""), .direct("What did you recover?", "\"Two tagged bottles of perfume, worth two hundred forty dollars, still in their boxes in {D.his} coat pocket.\""), .direct("Were the tags intact?", "\"Yes, each bottle still had the security tag attached, and the tags would have set off the alarm at the door.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} forgot the bottles were in {D.his} pocket after {D.he} tried a sample at the counter.\""), .cross("{DL} didn't try to run or fight?", "\"No, {D.he} stopped when I asked and came back inside with me without any trouble.\""), .cross("The tags didn't set off the alarm?", "\"They did not, because the alarm was being repaired and wasn't active at that door.\""), .cross("Samples are available at the counter?", "\"Yes, the counter has testers, but the testers are never in a sealed box like these bottles.\""), .cross("{DL} had money in {D.his} wallet?", "\"I saw a small amount of cash, but not nearly enough to pay for both bottles.\""), .cross("You didn't see {DL} take the bottles off the shelf?", "\"I saw it on the monitor and in person, so I'm sure of the moment {D.he} put them in the pocket.\"")],
        theory: ("{D} took perfume again.", "Forgotten samples."),
        allocution: "\"I forgot the perfume was in my pocket, and I was standing at the exit before it crossed my mind. I know the tags were cut, and I can only tell you that I didn't do it. I'm sorry to the security officer for the scene it caused in the store. I would have gone back and paid if I'd been given the chance.\"",
        truths: ("Tags were cut.", "{DL} passed registers."),
        defendant: [.direct("Did you put the perfume in your pocket?", "\"I picked up the bottles to smell them, and I put them in my pocket while I took a phone call, and then I forgot.\""), .direct("Why didn't you pay for them?", "\"I walked toward the exit without remembering. If I had remembered, I'd have gone back to the register.\""), .direct("What happened when the officer stopped you?", "\"I was surprised, and I told him I'd forgotten the bottles. I handed them over right away.\""), .direct("Did you plan to steal the perfume?", "\"No. I'd never plan to steal from a store where I shop. I'm embarrassed this happened at all.\""), .direct("What did you have with you to pay?", "\"I had a card in my wallet that had enough room to cover one of the bottles, though maybe not both.\""), .direct("What would you tell the store?", "\"I'm sorry for the trouble I caused. I should have paid for them first, and I won't carry anything unpaid again.\""), .cross("You've been caught taking items from a store before, haven't you?", "\"Yes, and I'm aware how this looks. I wish I could prove I forgot, but I can't.\""), .cross("You looked toward the exit as you put them away, didn't you?", "\"I may have, because I was on the phone and looking around. I wasn't watching for anyone.\""), .cross("You walked past every register?", "\"I did, and I should have stopped at one. I was distracted and I'm sorry.\""), .cross("Two bottles is a lot to forget, isn't it?", "\"It is, and I know that's hard to believe. It's what happened.\""), .cross("You'll stay out of the store?", "\"Yes, if the manager asks me to, and I'll pay any civil fee the store requires.\"")],
        openings: ("A security officer watched {D} pick up two bottles of perfume from a display and slip them into a coat pocket while looking toward the exit, and the tagged bottles were recovered, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} tried the bottles at the display and forgot they were in a coat pocket, a common mistake. {D} meant to pay for anything {D.he} carried to the register."),
        closings: ("The officer watched two tagged bottles slip into a pocket while {D} looked toward the exit, and after {PRIOR} {DL} knew what that is and where it leads.", "Forgetting a bottle in a pocket is a mistake, not a theft. The State must prove {D} meant to leave without paying, and a person who forgets is not a thief."),
        timeline: [(0, "{DL} browses."), (0, "Security stops {DL}.")],
        identified: "Perfume Bottles",
        mood: .indifferent)

    static let pizzaAgain = SmallCases.make(
        key: "story.followup.pizzaAgain",
        category: .whiteCollar,
        headlines: ["Fraudulent Pizza Order Picked Up Again"],
        law: "falsePretenses",
        spec: "Obtained pizza valued at $180 from {V}, a pizzeria, by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} picked up another order placed with a stolen card.",
        state: [E(.video, 3, "Counter Camera", "{D} picks up the order.")],
        defense: [E(.statement, 1, "Friend", "{DL} says a friend asked {D.him}.")],
        role: "Pizzeria owner",
        exam: [.direct("What is your business?", "\"I own a pizzeria, and a good share of our orders come through our website and phone with payment taken ahead.\""), .direct("What happened with the order?", "\"Someone ordered one hundred eighty dollars of pizzas and wings online, paid with a card, and sent {DL} to pick it up.\""), .direct("What did you learn about the card?", "\"The card was reported stolen, and the bank reversed the charge a few days later, so I lost both the food and the money.\""), .direct("What does the counter camera show?", "\"It shows {DL} walking in, giving the order number, and carrying out five boxes and two bags.\""), .direct("How did you know it was {DL}?", "\"The camera got a clear picture of {D.his} face, and a deputy recognized {D.him} from a past case.\""), .direct("What did {DL} say?", "\"{D.He} said a friend asked {D.him} to pick up the order and that {D.he} had no idea the card was stolen.\""), .cross("{DL} didn't place the order?", "\"The order came from an email account that isn't linked to {DL}, as far as I can tell.\""), .cross("{DL} didn't pay anything at the counter?", "\"No, because the order was prepaid. {D.He} only gave the number and took the boxes.\""), .cross("People send friends to pick up orders often, don't they?", "\"Yes, all the time, which is why we don't ask for ID on prepaid pickups.\""), .cross("You haven't found who placed the order?", "\"The sheriff's office is working on it, but so far the trail leads to a fake email address.\""), .cross("{DL} was polite at the counter?", "\"Yes, {D.he} was friendly, thanked my cashier, and left without any fuss.\"")],
        theory: ("{D} took a fraudulent order again.", "A friend's errand."),
        allocution: "\"I did pick up that pizza, but I did not place the order and I had no idea the card behind it was stolen. A friend asked me to grab it, and I thought nothing of it. I'm sorry that the owner lost money on a meal that no one paid for. I'd ask the court to see that I was used.\"",
        truths: ("The phone number matched.", "The friend had no phone."),
        defendant: [.direct("Did you know the card was stolen?", "\"No. I had no idea. A friend called me and asked me to pick up an order, and I said I'd do it.\""), .direct("Who is the friend?", "\"A man I know from work, and I'll give his name to the deputy as soon as we're finished here. He told me he was paying with his own card.\""), .direct("Did you get anything for picking up the food?", "\"He told me I could take a few slices for myself, and I ate one in the car. The rest I brought to him.\""), .direct("Why did you give the order number?", "\"He texted it to me, and that's what the pizzeria asks for. I didn't think there was anything unusual.\""), .direct("What did the deputy ask you?", "\"He asked who placed the order, and I showed him the texts with the friend and gave him the friend's name.\""), .direct("What would you tell the owner?", "\"I'm sorry about the loss. I wasn't trying to cheat you, and I'll cooperate in finding who used the card.\""), .cross("You've been charged with something like this before, haven't you?", "\"Yes, and I know it makes people doubt me. This time I truly didn't know about the card.\""), .cross("Your friend didn't pay you for the pickup?", "\"No, only pizza, and I see now that should have made me wonder.\""), .cross("You can show the court the texts?", "\"Yes, I have them on my phone, and I can hand the phone to the deputy.\""), .cross("You'd testify against your friend?", "\"If the texts show he used a stolen card, then yes, I'll tell the truth about it.\""), .cross("You'll check before picking up for anyone?", "\"I will, and I'll ask whose card was used before I walk into a restaurant to pick up anything.\"")],
        openings: ("Someone ordered $180 of pizzas and wings online with a stolen card and sent {D} to pick it up, and the counter camera shows {D} pick up the order, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say a friend asked {D} to pick up the food, and {D} did not know the card was stolen. {D} was running an errand."),
        closings: ("The camera shows {D} picking up an order paid for with a stolen card, and after {PRIOR} {DL} knew that picking up someone else's order carries a risk.", "A friend's errand is not a fraud, and {D} picked up food openly at the counter with a face the camera could see. The State must prove {D} knew the card was stolen."),
        timeline: [(0, "The order."), (0, "{DL} picks it up.")],
        identified: "Counter Camera",
        mood: .indifferent)

    static let shutoffAgain = SmallCases.make(
        key: "story.followup.shutoffAgain",
        category: .whiteCollar,
        headlines: ["Another Power-Cut Call Leads to Redeemed Cards"],
        law: "falsePretenses",
        spec: "Obtained $300 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} bought $300 in cards after a call, and {D}'s account redeemed them.",
        state: [E(.digital, 3, "Card Records", "Cards redeemed by {D}'s account.")],
        defense: [E(.statement, 1, "Reseller", "{DL} says {D.he} bought them secondhand.")],
        role: "Resident",
        exam: [.direct("What happened to you?", "\"I got a phone call from a man who said my power would be shut off within the hour unless I paid a past-due balance.\""), .direct("How did you pay?", "\"{D.He} told me to buy prepaid gift cards at a store and read {D.him} the numbers over the phone, which I did, for three hundred dollars.\""), .direct("When did you realize it was a scam?", "\"I called my real power company afterward, and they told me my account was current and that no such call had been made.\""), .direct("What did the card records show?", "\"The company that issued the cards showed they were redeemed within minutes by an online account in {DL}'s name.\""), .direct("Whose account was that?", "\"It was registered with {DL}'s email and phone number, and the redemptions were made from a device linked to {D.him}.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} bought those cards secondhand from a reseller and had no idea they came from a scam.\""), .cross("You never spoke with {DL}?", "\"No, the man on the phone gave no name, and I don't know whether it was {DL} or somebody else.\""), .cross("You gave the numbers to the caller, not {DL}?", "\"Yes, I read the numbers to whoever called, so I can't say who was on the line.\""), .cross("Resellers do sell used cards?", "\"I've heard of that, but the cards I bought were new and I read them out within minutes of buying them.\""), .cross("The loss was three hundred dollars?", "\"Yes, and I haven't gotten any of it back from the bank or the store.\""), .cross("You have the receipts?", "\"I kept the receipts from the store, which show the date and time of the purchases.\"")],
        theory: ("{D} redeemed scam cards again.", "A secondhand buyer."),
        allocution: "\"I did not call anyone or tell anyone their power would be cut off. I bought gift cards the way I always do, and I had no idea they were being used to cheat a person out of their money. I am sorry for what that resident went through. I'd ask the court to understand that I did not know how that account was being used.\"",
        truths: ("The account was new.", "No reseller exists."),
        defendant: [.direct("Did you redeem those gift cards?", "\"Yes, I redeemed them online. I bought them from a man on a trading site who sold them cheap.\""), .direct("How much did you pay for them?", "\"About two hundred dollars for cards with three hundred dollars of value, which I knew was a good price.\""), .direct("Did you know where they came from?", "\"No, I didn't ask. I thought they were extra cards someone had gotten as gifts and didn't need.\""), .direct("Did you call anyone about a power bill?", "\"No, I've never called anyone and said their power would be shut off. I don't know the person who did.\""), .direct("What did you do when the deputy contacted you?", "\"I showed him the messages with the seller and the payment record, and I gave him the seller's username.\""), .direct("What would you tell the victim?", "\"I'm sorry you lost your money. I didn't scam you, and I'll help the deputy find the person who did.\""), .cross("You've been charged with fraud before, haven't you?", "\"Yes, and I know that makes my story harder to believe. I'm telling the truth about this.\""), .cross("A discount of a third on gift cards seemed too good to be true, didn't it?", "\"Looking back it did, and I should have asked questions. At the time I was just happy for the deal.\""), .cross("You can't name the seller?", "\"I have a username and the messages, but not a real name. I'll give all of it to the deputy.\""), .cross("You used the cards right away?", "\"I redeemed them the same day, which I now see is part of why they were traced to me.\""), .cross("You'll repay the victim?", "\"I'll pay back what I can, and I'll stop buying cards from anyone I can't identify.\"")],
        openings: ("{V} got a call from a man who said {V.his} power would be shut off within the hour unless {V} paid a past-due balance, and {V} bought $300 in prepaid cards and read the numbers over the phone. The card records show {D}'s account redeemed them, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} bought the cards secondhand and did not know they came from a scam. {D} redeemed what {D.he} had bought."),
        closings: ("The card records show {D}'s account redeemed the scam cards {V} bought, and with {PRIOR} already on {D.his} record, {DL} knew exactly what a prepaid card scam looks like and who it targets.", "A secondhand card is not proof of a scam, and {D} redeemed cards {D.he} had bought from another seller. The State must prove {D} knew the cards came from a scam."),
        timeline: [(0, "The call."), (1, "The cards are redeemed.")],
        identified: "Card Records",
        mood: .indifferent)

    static let lockedAgain = SmallCases.make(
        key: "story.followup.lockedAgain",
        category: .whiteCollar,
        headlines: ["Locked Phone Sold Again"],
        law: "falsePretenses",
        spec: "Obtained $300 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sold another locked phone for $300.",
        state: [E(.document, 3, "Carrier Notice", "The phone is locked and reported lost.")],
        defense: [E(.statement, 1, "Unaware", "{DL} says {D.he} did not know.")],
        role: "Buyer",
        exam: [.direct("What did you buy?", "\"I bought a used phone for three hundred dollars from {DL}, who posted it for sale online and said it was in perfect shape.\""), .direct("What did {DL} tell you about it?", "\"{D.He} said it was unlocked, worked on any carrier, and had no problems, and I paid in cash when we met.\""), .direct("What went wrong?", "\"When I put in my SIM card, the phone wouldn't work, and it showed a message saying it was locked to another account.\""), .direct("What did the carrier say?", "\"The carrier sent a notice saying the phone had been reported lost and was blocked from use on any network.\""), .direct("Did you ask {DL} to fix it?", "\"I texted {D.him} several times and asked for a refund, but {D.he} stopped answering after the second message.\""), .direct("What did {DL} say afterward?", "\"{D.He} said {D.he} didn't know the phone was locked and had bought it from someone else.\""), .cross("You met {DL} in person?", "\"Yes, in a parking lot, and I looked at the phone briefly before I paid.\""), .cross("You didn't test it with your SIM at that time?", "\"No, I only turned it on and looked at the screen. I should have put in my card.\""), .cross("{DL} never said the phone was reported lost?", "\"No, never, and that's why I felt I'd been misled.\""), .cross("{DL} may not have known about the block?", "\"It's possible, but {D.he} told me it was unlocked and never checked with the carrier, as far as I know.\""), .cross("You still have the phone?", "\"Yes, I brought it with me, along with the carrier's notice.\"")],
        theory: ("{D} sold a locked phone again.", "An unaware seller."),
        allocution: "\"I did not know that phone was locked when I sold it, and I offered the buyer the money back as soon as {V.he} told me. I buy and sell used phones to get by, and I'm sorry that this one turned out to be worthless. I never wanted to take anyone's three hundred dollars for nothing.\"",
        truths: ("{DL} sold two more.", "{DL} bought a lot."),
        defendant: [.direct("Where did you get the phone?", "\"I bought it from a man at a flea market who said it was his old phone and that he'd upgraded.\""), .direct("Did you check it before you sold it?", "\"I turned it on and made sure it worked, but I didn't call the carrier or check the account.\""), .direct("Did you know it was locked?", "\"No. If I had known, I'd never have sold it. I only wanted my money back, and I thought it was a good phone.\""), .direct("What did you tell the buyer?", "\"I said it was unlocked because that's what I'd been told. I didn't have any reason to doubt it.\""), .direct("Why did you stop answering the buyer's texts?", "\"I was embarrassed and didn't know how to fix it. I should have offered the money back right away.\""), .direct("What would you tell the buyer?", "\"I'm sorry for the trouble. I'll refund the three hundred dollars, and I'll look for the man I bought it from.\""), .cross("You've sold phones with problems before, haven't you?", "\"Yes, and that's why I should have been much more careful about checking this one.\""), .cross("You told the buyer it was unlocked without checking?", "\"I did, and I was wrong to pass along a claim I never verified myself.\""), .cross("You sold it for what you paid for it?", "\"I made a small profit, about sixty dollars, and I'll return that as well.\""), .cross("You didn't give the buyer a way to reach you?", "\"I gave my number, but I stopped replying, which was the wrong decision.\""), .cross("You can show where you bought it?", "\"I have a text from the seller, and I'll hand it to the deputy.\"")],
        openings: ("After {PRIOR}, {D} sold another locked phone for $300, and the buyer says {D} claimed it was unlocked and worked on any carrier. The carrier's notice shows the phone was locked and reported lost, and {DL} had been before this court in {PRIORDATE}.", "The defense will say {D} had no idea the phone was locked or had been reported lost, and sold it as {D.he} received it. {D} is an unaware seller, not a person who set out to deceive a buyer."),
        closings: ("A buyer paid $300 in cash for a phone described as unlocked, and the carrier shows it was locked and reported lost. After {PRIOR}, {DL} knew exactly what a phone listing promises and what it must be.", "{D} passed along a phone as {D.he} got it, and the carrier's notice does not show what {D} knew when {D.he} listed it. The State must prove {D} knew the phone was locked and lost."),
        timeline: [(0, "The sale."), (0, "The carrier refuses it.")],
        identified: "Carrier Notice",
        mood: .indifferent)

    static let towAgain = SmallCases.make(
        key: "story.followup.towAgain",
        category: .whiteCollar,
        headlines: ["Tow Fees Questioned Again"],
        law: "falsePretenses",
        spec: "Obtained $260 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} charged $260 to release a car against a $170 posted rate.",
        state: [E(.document, 3, "Rate Sheet", "The posted total was $170.")],
        defense: [E(.statement, 1, "Storage", "{DL} says storage was extra.")],
        role: "Car owner",
        exam: [.direct("What happened to your car?", "\"It was towed from a lot after a parking dispute, and I went to the tow yard to get it back that evening.\""), .direct("What did you expect to pay?", "\"The sign at the yard and the rate sheet from the county listed a total of one hundred seventy dollars for a release.\""), .direct("What did {DL} charge you?", "\"{DL} charged me two hundred sixty dollars and told me I couldn't leave with the car unless I paid in full.\""), .direct("What explanation did you get?", "\"{D.He} said there was a storage fee on top of the posted rate, but {D.he} didn't show me where that was written.\""), .direct("What did the rate sheet say?", "\"It said the total was one hundred seventy dollars for a standard tow, including the hookup and the first day of storage.\""), .direct("What did you do?", "\"I paid because I needed my car for work the next morning, and I asked for a receipt that listed the charges.\""), .cross("Storage fees can be charged separately?", "\"Sometimes, but this sheet said the first day of storage was already included in the total.\""), .cross("{DL} gave you a receipt?", "\"Yes, and it lists the storage fee as a separate line, which I think was added after the fact.\""), .cross("You didn't argue at the yard?", "\"I argued a little, but {DL} wouldn't release the car, so I paid and left.\""), .cross("Your car was kept there overnight?", "\"It was there for about five hours, not an entire day, so I don't see how storage cost ninety dollars.\""), .cross("You've filed a complaint with the county?", "\"Yes, I did, which is how the sheriff's office got the rate sheet and the receipt.\"")],
        theory: ("{D} overcharged again.", "Storage fees."),
        allocution: "\"The storage fee is part of what we charge, and I believed the rate was posted inside the office where customers sign. I understand that the car owner felt the price jumped, and I'm sorry that {V.he} was surprised at a hard moment. I will post the rates plainly from now on, and I'll answer for any mistake I made.\"",
        truths: ("Storage was listed as included.", "No daily rate posted."),
        defendant: [.direct("Why did you charge two hundred sixty dollars?", "\"The base tow rate is one hundred seventy dollars, and I added a storage fee because the car sat in my yard past closing.\""), .direct("Did you tell the owner about the storage fee?", "\"I told {V.him} when {V.he} arrived, and I thought {V.he} understood. I may not have explained it as clearly as I should have.\""), .direct("Where is the storage fee posted?", "\"It's on the back of the rate sheet in smaller print, and it's also on a sign by my office window.\""), .direct("Did you refuse to release the car?", "\"I told {V.him} {V.he} had to pay before I could let it go. That's my policy for every customer who comes to the yard.\""), .direct("Did you mean to overcharge anyone?", "\"No. I follow the rates the county approved, and I'm sure the storage fee is part of them.\""), .direct("What would you tell the car owner?", "\"I'm sorry for the confusion about the fee. If the court says I overcharged, I'll return the difference.\""), .cross("You have been before this court over tow fees before, haven't you?", "\"Yes, and I told the judge I'd post my rates plainly. I'm working on that.\""), .cross("The front of the rate sheet says one hundred seventy dollars total, right?", "\"It does, and I see how a customer could read it that way.\""), .cross("Five hours of storage doesn't cost ninety dollars, does it?", "\"Under the full-day rule it does, though I understand that seems steep for five hours.\""), .cross("You wouldn't give the car back unless the whole amount was paid?", "\"That's my rule, and I'll review it with the county.\""), .cross("You'll refund ninety dollars if asked?", "\"Yes, if the court finds I'm wrong, I'll refund it without delay.\"")],
        openings: ("{V} went to the tow yard that evening to get a car back after a parking dispute, and {D} charged $260 against a posted rate of $170. The county's rate sheet lists the total, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say the extra amount was storage, which the posted sign did not mention but the contract allows. {D} billed what the yard has always billed for storage."),
        closings: ("The sign and the county rate sheet both say $170 for a release, and {D} charged $260. After {PRIOR}, {DL} knew exactly what the posted rate was.", "Storage is a separate charge that is common at tow yards, and {D} did not hide it. The State must prove {D} meant to charge more than the law allows."),
        timeline: [(0, "The car is towed."), (1, "{V} pays.")],
        identified: "Rate Sheet",
        mood: .indifferent)

    static let bassAgain = SmallCases.make(
        key: "story.followup.bassAgain",
        category: .publicOrder,
        headlines: ["Car Stereo Noise Again at Night"],
        law: "disorderly",
        spec: "Disturbed the peace by making loud noise in a residential area at night, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}'s stereo was heard again at 2 a.m. after the earlier warning.",
        state: [E(.statement, 3, "Deputy", "The bass was audible from 200 feet.")],
        defense: [E(.statement, 1, "Low", "{DL} says it was low.")],
        role: "Sheriff's deputy",
        exam: [.direct("What is your assignment?", "\"I'm a patrol deputy, and I answer noise and disturbance complaints in the residential parts of the county.\""), .direct("What brought you to the street that night?", "\"A neighbor called around two in the morning about loud music, and I drove to the block to check.\""), .direct("What did you hear?", "\"From two hundred feet away I could hear heavy bass thumping and feel it in my chest through the patrol car.\""), .direct("Where was it coming from?", "\"From a car parked in the driveway at {DL}'s house, with the doors open and the stereo turned up.\""), .direct("Had {DL} been warned before?", "\"Yes, I'd spoken to {D.him} a few weeks earlier after another complaint, and {D.he} promised to keep it down.\""), .direct("What did {DL} say that night?", "\"{D.He} said the music was low and that the neighbors were exaggerating because they didn't like {D.him}.\""), .cross("It was a weekend night?", "\"Yes, a Saturday into Sunday, though two in the morning is still a time when most people are asleep.\""), .cross("You measured the volume with a meter?", "\"No, I didn't have one with me, so I relied on what I could hear from the street.\""), .cross("{DL} turned it off when you asked?", "\"Yes, right away, and {D.he} was polite about it.\""), .cross("Only one neighbor called?", "\"One called that night, though two told me later that they'd been kept awake.\""), .cross("{DL} wasn't impaired?", "\"I didn't notice any signs of that, and {D.he} seemed clear and cooperative.\"")],
        theory: ("{D} blasted the stereo again.", "A low volume."),
        allocution: "\"I did not think the music was that loud, and I forgot about the warning from the earlier visit. I understand now that it carried through the neighborhood at two in the morning, and I'm sorry that people had their sleep broken. I will keep the volume down, and I'll be a better neighbor going forward.\"",
