        identified: "Custodian",
        mood: .indifferent)

    static let tailgateAgain = SmallCases.make(
        key: "story.followup.tailgateAgain",
        category: .traffic,
        headlines: ["Tailgating Again on the Highway"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others, on {DATE}.",
        ages: 18...60,
