        exam: [.direct("What is your job?", "\"I'm a parking enforcement officer, and I write citations and patrol the lots and streets in town.\""), .direct("What did you find?", "\"Fake parking citations on the windshields of about fifteen cars in a lot, printed on paper that looked a lot like ours.\""), .direct("How could you tell they weren't real?", "\"They had the wrong form number, the wrong logo, and a payment address that isn't ours, though the layout was close.\""), .direct("Who made them?", "\"Printed forms found in {DL}'s car matched the ones on the windshields, and a witness saw {DL} walking along the cars.\""), .direct("What was the purpose of the forms?", "\"They told drivers to mail fifty dollars to an address, and a few people had already sent money before we learned of it.\""), .direct("What did {DL} say?", "\"{D.He} said it was a prank and that {D.he} didn't expect anyone to take it seriously or send money.\""), .cross("The forms don't use a real officer's name?", "\"No, they list a made-up badge number.\""), .cross("Nobody was hurt by this?", "\"Some people lost fifty dollars each, but none of them lost more than that.\""), .cross("The address on the forms is a post office box?", "\"Yes, and the sheriff's office is looking into who rents it.\""), .cross("{DL} was cooperative?", "\"Yes, {D.he} admitted printing the forms when the deputy asked.\""), .cross("There's no evidence {DL} received money?", "\"Not that we've found so far, though we're still checking the box.\"")],
        theory: ("{D} forged citations again.", "A prank."),
        allocution: "\"The citations were meant as a prank, and it went too far. I did not think anyone would pay one, and I'm sorry that someone did. I know the parking staff have a real job and these fakes made it harder. I'll pay back what was lost and stay away from jokes like that.\"",
        truths: ("One person paid.", "The P.O. box was {DL}'s."),
        defendant: [.direct("Did you make those citations?", "\"I printed them from a template I found online, but I never meant to defraud anyone.\""), .direct("Why did you do it?", "\"A friend and I thought it would be funny to put fake tickets on cars at a busy lot. It was a prank.\""), .direct("Did you put an address on them?", "\"I put a post office box that I'd rented months ago and still had, thinking nobody would write to it.\""), .direct("Did you receive any money?", "\"I opened the box and found three envelopes with cash. I didn't spend it, and I was shocked that anyone had sent it.\""), .direct("What did you do with that money?", "\"I kept it in the box. I didn't know how to return it without admitting what I'd done.\""), .direct("What would you tell the people who paid?", "\"I'm sorry. I'll return every dollar and apologize to each of you if the court lets me.\""), .cross("You were in court for something like this before, weren't you?", "\"Yes, and I knew better. I told the judge I'd never do anything like it again.\""), .cross("You put a real address on a prank?", "\"I did, and that turned a joke into a fraud. I understand that now.\""), .cross("You opened the box and saw money?", "\"I did, and I should have stopped and returned it that day.\""), .cross("People who sent money believed they owed a fine?", "\"They did, and they trusted the form, which is why I feel awful.\""), .cross("You'll return the money?", "\"Yes, all of it, with a note explaining it was a mistake.\"")],
