        key: "story.followup.gymBreakAgain",
        category: .property,
        headlines: ["Another Truck Window Smashed Outside a Gym"],
        law: "breakingVehicle",
        spec: "Broke or entered a motor vehicle of {V} with intent to commit larceny therein, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} smashed a window outside a different gym and took a bag.",
        state: [E(.video, 3, "Lot Camera", "{D} smashes the window.")],
        defense: [E(.statement, 1, "Found Bag", "{DL} says {D.he} found it.")],
        role: "Truck owner",
        exam: [.direct("What happened to your truck?", "\"I parked it outside a gym at night, and in the morning the passenger window was smashed and a bag was gone from the seat.\""), .direct("What was in the bag?", "\"A work bag with tools, a phone charger, and some paperwork, worth maybe a few hundred dollars, plus the window repair.\""), .direct("What does the lot camera show?", "\"It shows {DL} walking up to the truck, striking the window with a hard object, reaching in, and walking away with a bag.\""), .direct("Did you recognize {DL}?", "\"Not at first, but the deputy told me {D.he} had been charged with something similar at another gym.\""), .direct("Where was the bag found?", "\"In {DL}'s car a few days later, when a deputy stopped {D.him} and saw the bag on the back seat.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} found the bag on the ground and didn't know where it came from.\""), .cross("The video is dark?", "\"It's nighttime, but the lot has lights, and the picture is clear enough to see {D.him} swing at the window.\""), .cross("The bag looks similar to others?", "\"It looks like many work bags, but this one has a patch on the side that matches mine.\""), .cross("{DL} didn't try to hide the bag?", "\"It was in plain view, on the seat of the car.\""), .cross("Your tools were still in it?", "\"Most of them, though a drill and the charger were gone.\""), .cross("You have no photo of the bag?", "\"I have an older photo of me holding it, which shows the patch.\"")],
        theory: ("{D} broke into another truck.", "A found bag."),
        allocution: "\"I did not smash that truck window, and I never would have. I found a bag near the lot and picked it up, and I should have handed it to the gym desk. I'm sorry that the owner had a broken window and a missing bag. I'd ask the court to see I wasn't the one who broke it.\"",
        truths: ("Glass was on {DL}'s shoes.", "The bag had tags."),
        defendant: [.direct("Where did you find the bag?", "\"I found it on the ground next to a dumpster, near the lot. It looked like someone had thrown it out.\""), .direct("Why did you take it?", "\"I thought it was trash, and I was curious. I picked it up and put it in my car without looking inside.\""), .direct("Did you break the window?", "\"No. I've never broken a truck window. I wasn't even at that gym that night.\""), .direct("What does the video show?", "\"It shows someone who looks like me, but I think it's a different person. I can't explain the resemblance.\""), .direct("What did you tell the deputy?", "\"I told {OFF.him} where I found the bag and offered to take {OFF.him} to the dumpster. {OFF.He} didn't want to go.\""), .direct("What would you tell the truck owner?", "\"I'm sorry you lost your things. I'll return everything that's still in the bag, and I didn't break your window.\""), .cross("You've been charged with smashing a car window before, haven't you?", "\"Yes, and I know that's why you suspect me. I'm telling you I didn't do this one.\""), .cross("You had the bag in your car?", "\"I did, and I know that looks bad. I didn't look inside it.\""), .cross("The patch on the bag matches the owner's?", "\"It does, and that's the only thing I can't explain.\""), .cross("You could have taken it to the sheriff's office?", "\"I could have, and I should have. I'm sorry I didn't.\""), .cross("You'll return everything in the bag?", "\"Yes, every piece that's still there, and I'll pay for what's missing.\"")],
        openings: ("{V} parked outside a gym at night and found the passenger window smashed and a work bag with tools, a charger and paperwork gone, and the lot camera shows {D} smash a window, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} found the bag on the ground and did not break anything. A bag lying in a lot is not a theft."),
        closings: ("The lot camera shows {D} smash the passenger window and take a bag from the seat, and after {PRIOR} {DL} knew exactly what that does to a car and to its owner.", "A found bag is not a stolen bag, and a camera at night is not a clear picture. The State must prove {D} broke the window."),
        timeline: [(0, "The window breaks."), (1, "{V} reports it.")],
        identified: "Lot Camera",
        mood: .indifferent)

    static let bikeFleeAgain2 = SmallCases.make(
        key: "story.followup.bikeFleeAgain2",
        category: .traffic,
        headlines: ["Cyclist Flees Deputy Again"],
        law: "fleeing",
        spec: "Operated a bicycle on a street while fleeing a law enforcement officer, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} pedaled away from a deputy again after an earlier case.",
        state: [E(.video, 3, "Body Camera", "{D} pedals away.")],
        defense: [E(.statement, 1, "No Light", "{DL} says {D.he} did not hear.")],
        role: "Sheriff's deputy",
        exam: [.direct("What is your assignment?", "\"I'm a patrol deputy, and I wear a body camera during every traffic and pedestrian contact on my shift.\""), .direct("What did you see that evening?", "\"I saw a person riding a bicycle without a light on a dark road, so I turned on my lights and called out to stop.\""), .direct("Who was riding?", "\"{DL}, whom I recognized from an earlier encounter in which {D.he} also rode away from me.\""), .direct("What did {DL} do?", "\"{D.He} looked back at me, then pedaled faster, cut across a lawn, and kept going down the next street.\""), .direct("What does your body camera show?", "\"It shows me calling out 'Sheriff's office, stop,' and {DL} turning to look and then pedaling away.\""), .direct("What did {DL} say when you caught up?", "\"{D.He} said {D.he} didn't hear me and was only rushing home because it was getting late.\""), .cross("You were in a patrol car with the lights on?", "\"Yes, and I used the siren briefly as well, though I was behind {D.him} the whole time.\""), .cross("{DL} was wearing headphones?", "\"I noticed a cord by {D.his} neck, so it's possible {D.he} had earbuds in.\""), .cross("You didn't have to chase far?", "\"About two blocks, and {D.he} stopped when I pulled alongside.\""), .cross("{DL} wasn't armed or doing anything else illegal?", "\"No, {D.he} had no weapon and nothing unlawful on {D.him}.\""), .cross("The bicycle had no light?", "\"Correct, which is why I tried to stop {D.him} in the first place.\"")],
        theory: ("{D} fled on a bike again.", "A cyclist who did not hear."),
        allocution: "\"I never heard the deputy call out, and I was late for my shift, so I was pedaling hard. I looked back only because of the traffic behind me. I'm sorry that it seemed like I was running from an officer. I have a lot of respect for the sheriff's office and wouldn't flee on purpose.\"",
        truths: ("{DL} looked back.", "No headphones."),
        defendant: [.direct("Did you see the deputy's lights?", "\"I saw a flash behind me at some point, but I thought it was a car turning, and I didn't realize it was meant for me.\""), .direct("Why were you riding without a light?", "\"The battery in my front light had died that morning, and I hadn't had time to replace it before I rode home.\""), .direct("Did you hear the deputy call out?", "\"No. I had earbuds in listening to music, and the traffic was loud enough that I didn't hear anything.\""), .direct("Why did you pedal faster?", "\"I was in a hurry to get home, and I wasn't thinking about the car behind me.\""), .direct("What did you do when the deputy pulled alongside?", "\"I stopped right away and took out my earbuds. I told {OFF.him} I hadn't heard {OFF.him} calling out.\""), .direct("What would you tell the court?", "\"I'm sorry for the confusion. I wasn't trying to run, and I'll use lights and keep my earbuds out when I ride at night.\""), .cross("You ran from a deputy once before, didn't you?", "\"Yes, and that's why I should have paid more attention. I wasn't trying to make the same mistake.\""), .cross("You looked back at the deputy, didn't you?", "\"I did glance back, but all I saw was headlights. I didn't know it was a patrol car.\""), .cross("Earbuds in a dark street isn't safe, is it?", "\"No, it isn't, and I'll leave them out from now on.\""), .cross("You crossed a lawn to get away?", "\"I cut across to save time, not to get away. That was a bad habit, and I'll stay on the road.\""), .cross("You'll buy a light today?", "\"Yes, I'll buy one on my way home and keep spare batteries in my pack.\"")],
        openings: ("A deputy saw a person riding a bicycle without a light on a dark road, turned on the lights and called out to stop, and the body camera shows {D} pedal away, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} did not hear the deputy over the wind and the road, and never knew {D.he} was being stopped. {D} did not mean to flee."),
        closings: ("The body camera shows {D} pedal away after the deputy's lights came on, and with {PRIOR} already on {D.his} record, {DL} knew exactly what the lights and the call to stop mean on a dark road.", "A cyclist who did not hear is not a fleeing suspect. The State must prove {D} knew the deputy was trying to stop {D.him}."),
        timeline: [(0, "The order."), (0, "The chase.")],
        identified: "Body Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let cardSwapAgain = SmallCases.make(
        key: "story.followup.cardSwapAgain",
        category: .whiteCollar,
        headlines: ["Cloned Card Used at Another Pump"],
        law: "cardFraud",
        spec: "Obtained gasoline valued at $80 from {V}, a gas station, by card fraud, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} used a cloned card at a different pump.",
        state: [E(.video, 3, "Pump Camera", "{D} swipes a card.")],
        defense: [E(.statement, 1, "Borrowed Card", "{DL} says a friend gave {D.him} the card.")],
        role: "Station clerk",
        exam: [.direct("What is your job?", "\"I'm a clerk at a gas station, and I watch the pumps and the register through the window during my shift.\""), .direct("What did you notice?", "\"A customer fueled up at pump four and the card came back with a notice from the payment system flagged as possible fraud.\""), .direct("What does the pump camera show?", "\"It shows {DL} swiping a card at the pump, filling a truck with about eighty dollars of gasoline, and leaving.\""), .direct("How was the card flagged?", "\"The bank reported that the card number had been cloned and used at several stations that same week.\""), .direct("Who was the cardholder?", "\"A woman in another county, who told the bank she never made a purchase here and still had her card in her purse.\""), .direct("What did {DL} say when asked?", "\"{D.He} said a friend gave {D.him} the card to buy gas and that {D.he} had no idea it was cloned.\""), .cross("{DL} paid at the pump, not inside?", "\"Yes, and that's why we didn't speak with {D.him} that day.\""), .cross("The camera doesn't show the card number?", "\"No, it shows only the swipe and the screen, which isn't legible.\""), .cross("{DL} didn't try to hide {D.his} face?", "\"No, {D.he} looked right at the camera as {D.he} filled the tank.\""), .cross("The loss was eighty dollars?", "\"Yes, and the bank has refunded the cardholder, but not us.\""), .cross("{DL} has not been back?", "\"No, I haven't seen {D.him} or the truck since.\"")],
        theory: ("{D} used a cloned card again.", "A friend's card."),
        allocution: "\"I used a card that a friend gave me, and I truly thought it was theirs to give. I did not know the card was cloned, and I'm sorry that the station lost the gas money. I should have asked more questions before I pumped. I'll cooperate however the court wants to find out who gave it to me.\"",
        truths: ("Cards were in the console.", "The friend is unknown."),
        defendant: [.direct("Whose card was it?", "\"It belonged to a friend who gave it to me and said it was his and that I could use it to pay for gas.\""), .direct("Did you know it was cloned?", "\"No. It looked like a normal card, and my friend told me he was paying me back for helping him move.\""), .direct("What was your friend's name?", "\"I'd rather give it directly to the deputy, but I can tell you he's someone I've known for a few years.\""), .direct("Why didn't you use your own card?", "\"I was low on money until payday, and my friend said he'd pay me back in gas. It seemed like a fair deal.\""), .direct("What did you do after you heard it was cloned?", "\"I called my friend and he stopped answering. I told the deputy everything I knew about him.\""), .direct("What would you tell the station?", "\"I'm sorry for the loss. I didn't know the card was bad, and I'll pay the eighty dollars if the court orders it.\""), .cross("You've been in court for card fraud before, haven't you?", "\"Yes, and I know how that makes this look. I'm not asking you to ignore it.\""), .cross("You used a card that wasn't yours?", "\"I did, but I believed my friend had the right to give it to me.\""), .cross("You don't have the friend's address?", "\"I have a phone number that no longer works, and I've given it to the deputy.\""), .cross("You looked straight at the camera?", "\"I did, because I had no reason to hide. If I'd known, I would have stayed away from that station.\""), .cross("You'll avoid using anyone else's cards?", "\"Yes, I won't use a card unless my name is on it.\"")],
        openings: ("A customer fueled up at pump four and the card came back flagged as possible fraud, and the pump camera shows {D} swipe a card, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say a friend gave {D} the card to use, and {D} did not know it was cloned. {D} used what {D.he} was handed."),
        closings: ("The pump camera shows {D} swiping a card the system flagged, and having faced {PRIOR} before, {DL} understood exactly what a cloned card is.", "A card from a friend looks like any other card at a pump, and {D} used what {D.he} was handed. The State must prove {D} knew the card was cloned when {D.he} swiped it."),
        timeline: [(0, "The swipe."), (1, "The bank flags it.")],
        identified: "Pump Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let passwordAgain = SmallCases.make(
        key: "story.followup.passwordAgain",
        category: .cyber,
        headlines: ["Ex Logs Into Another Account"],
        law: "accessingComputers",
        spec: "Willfully accessed the computer account of {V} without authority, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} logged into another shared account after an earlier case.",
        state: [E(.digital, 3, "Account Log", "The password changed.")],
        defense: [E(.statement, 1, "Shared", "{DL} says it was shared.")],
        role: "Account owner",
        exam: [.direct("What account was affected?", "\"A shared online account that my household uses for streaming, shopping, and a few small bills.\""), .direct("What did you notice?", "\"One morning my password stopped working, and I got an email saying the password had been changed from another device.\""), .direct("What does the account log show?", "\"It shows a login from a computer in another town, a password change, and then a series of purchases and downloads.\""), .direct("Who owns that device?", "\"The log traces to a computer at an address that matches {DL}, a person I used to share the account with.\""), .direct("What did you do?", "\"I reported the change to the company, recovered the account, and reported it to the sheriff's office.\""), .direct("What did {DL} say?", "\"{D.He} said the password was shared and that {D.he} had every right to log in.\""), .cross("You shared the password with {DL} once?", "\"Yes, a long time ago when we lived in the same house.\""), .cross("{DL} never changed it before?", "\"Not that I know of. This was the first time the password was changed.\""), .cross("The account is in your name?", "\"Yes, my name, my email, and my payment card.\""), .cross("The purchases were small?", "\"A few downloads and a subscription, totaling about thirty dollars.\""), .cross("You told {DL} to stop using it?", "\"I did, in a text months ago, and I haven't heard back.\"")],
        theory: ("{D} took over an account again.", "A shared account."),
        allocution: "\"That account was half mine, because I paid half of it for two years. I changed the password because I was angry about how things ended between us. I know now it was wrong, since {V.he} had asked me to leave it alone. I'm sorry for the trouble it caused, and I'll stay out of it.\"",
        truths: ("{V} had asked for it to be left alone.", "{DL} paid half."),
        defendant: [.direct("Did you log in to the account?", "\"Yes, I logged in with the password I'd always used. It was shared when we lived together.\""), .direct("Did you change the password?", "\"I did, because the site asked me to update it, and I didn't think the owner would mind.\""), .direct("Did you know you were told to stay out?", "\"I got a text a while back, but I thought it was angry and not serious. I should have taken it seriously.\""), .direct("What did you buy or download?", "\"A few shows and a subscription that I'd been using for years. I thought it was part of what we'd always shared.\""), .direct("What did you do after the company contacted you?", "\"I logged out and haven't used it since. I told the deputy what I did, and I haven't tried to hide it.\""), .direct("What would you tell the account owner?", "\"I'm sorry for using your account without asking. I'll repay the thirty dollars and never log in again.\""), .cross("You'd been accused of accessing someone else's account before, hadn't you?", "\"Yes, and I should have known not to try again. That's my mistake.\""), .cross("Changing a password locked the owner out, didn't it?", "\"It did, and I'm sorry for the trouble that caused.\""), .cross("The owner told you not to use it?", "\"Yes, and I ignored the text. I'm not proud of that.\""), .cross("You used it from another town?", "\"I was visiting family and I wanted to watch a show. I didn't think about the consequences.\""), .cross("You'll delete any saved passwords?", "\"Yes, I'll clear them from every device I own.\"")],
        openings: ("One morning {V}'s password stopped working and {V.he} got an email saying it had been changed from another device, and the account log shows the change, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say the account was shared by the household and {D} had always used it. {D} changed the password as a user of the account."),
        closings: ("The account log shows the password changed from another device, {V} was locked out that morning, and since {PRIOR}, {DL} could not have missed what changing a password does to the person locked out.", "A shared account is used by everyone who shares it. The State must prove {D} had no right to change the password."),
        timeline: [(0, "The log-in."), (1, "{V} is locked out.")],
        identified: "Account Log",
        mood: .indifferent,
        genders: ["D": .female])

    static let permitFeeAgain = SmallCases.make(
        key: "story.followup.permitFeeAgain",
        category: .whiteCollar,
        headlines: ["Permit Help Fee Taken Again"],
        law: "falsePretenses",
        spec: "Obtained $400 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} took $400 to arrange a vendor permit and filed nothing.",
        state: [E(.digital, 3, "Texts", "{D} promises a permit.")],
        defense: [E(.statement, 1, "Delay", "{DL} says the county was slow.")],
        role: "Vendor",
        exam: [.direct("What is your business?", "\"I sell crafts at fairs and markets, and I need a vendor permit from the county for each season.\""), .direct("How did you meet {DL}?", "\"{DL} told me {D.he} helped vendors get permits faster, and {D.he} offered to handle the paperwork for a fee.\""), .direct("What did you pay?", "\"Four hundred dollars, which I sent to {D.him} by transfer after we agreed on the arrangement by text.\""), .direct("What did {DL} promise?", "\"{D.He} promised to file the application, pay the county fee, and have the permit in my hands before the first market.\""), .direct("What happened?", "\"The first market came and went with no permit, and I couldn't sell. When I called the county, they had no application in my name.\""), .direct("What did {DL} say?", "\"{D.He} said the county was slow and that the application was in the queue, but {D.he} never showed me a receipt.\""), .cross("The county is sometimes slow?", "\"It can be, but an application would at least show up in their system.\""), .cross("{DL} has returned any money?", "\"No, not a dollar, though {D.he} keeps promising to.\""), .cross("You have the texts?", "\"Yes, I saved every text, including the promise to file.\""), .cross("You didn't check with the county first?", "\"I should have, and I know it. I trusted {D.him} because {D.he} sounded sure.\""), .cross("The market fee was also lost?", "\"Yes, I paid a booth deposit that I couldn't use, which was another hundred dollars.\"")],
        theory: ("{D} took money for no permit again.", "A slow county."),
        allocution: "\"I collected those fees believing the county would process the permits, and I thought the paperwork was just slow. I did file what I could, and I never meant to take anyone's money for nothing. I'm sorry to the vendors who have been waiting and who lost sales while they did. I'll return every dollar if the permits don't come through.\"",
        truths: ("The county has no filing.", "Two vendors paid."),
        defendant: [.direct("Did you file the permit application?", "\"I started it, but I never finished. I got behind and didn't have the county's forms ready when the market opened.\""), .direct("Where did the four hundred dollars go?", "\"I used part of it for my own bills, and part for a trip I had planned. I meant to cover the fee later.\""), .direct("Why did you say the county was slow?", "\"I didn't want to admit I hadn't filed yet. It was easier to blame the county than to tell the truth.\""), .direct("Did you plan to cheat the vendor?", "\"No. I meant to file and I told myself I'd catch up. I got in over my head.\""), .direct("Did you try to return the money?", "\"I offered once, but I didn't have it. I should have called and said so rather than putting it off.\""), .direct("What would you tell the vendor?", "\"I'm sorry for the lost market and the money. I'll repay four hundred dollars and the booth deposit.\""), .cross("You've been convicted of taking payment for services you didn't provide before, haven't you?", "\"Yes, and I told the judge then that I was finished with it. I didn't.\""), .cross("You spent the money on a trip?", "\"Part of it, and I'm ashamed of that.\""), .cross("You told the vendor the application was in a queue?", "\"I did, and it wasn't true. I lied.\""), .cross("How will you repay four hundred dollars?", "\"I'll pay a hundred a month from my job until it's paid.\""), .cross("You'll stop offering this service?", "\"Yes, I won't take payment for permits or any paperwork again.\"")],
        openings: ("{D} told {V}, who sells crafts at fairs, that {D.he} helped vendors get permits faster, took $400 to handle the paperwork, and filed nothing, and the texts show {D} promised a permit, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say the county was slow and {D} was still waiting on the paperwork, a delay that has nothing to do with intent. {D} meant to deliver the permit."),
        closings: ("The texts show {D} promising a permit, the county has no filing, and after {PRIOR} {DL} knew what taking a fee means.", "A slow county is not a scheme to cheat, and {D} was still waiting on the filing. The State must prove {D} never meant to file the paperwork when {D.he} took the $400."),
        timeline: [(-10, "{V} pays."), (0, "{V} calls the county.")],
        identified: "Texts",
        mood: .indifferent,
        genders: ["D": .male])

    static let chargerAgain = SmallCases.make(
        key: "story.followup.chargerAgain",
        category: .property,
        headlines: ["Waiting Room Theft Again"],
        law: "misdLarceny",
        spec: "Stole a phone valued at $300 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} took a phone from a clinic waiting room.",
        state: [E(.video, 3, "Clinic Camera", "{D} takes the phone.")],
        defense: [E(.statement, 1, "Mix-Up", "{DL} says {D.he} thought it was {D.his}.")],
        role: "Clinic staff",
        exam: [.direct("What is your job?", "\"I work at the front desk of a medical clinic, and I check patients in and watch the waiting room.\""), .direct("What happened in the waiting room?", "\"A patient left a phone on a chair beside the charging station while they went back for an appointment.\""), .direct("What does the clinic camera show?", "\"It shows {DL} sitting next to the chair, glancing around, picking up the phone, and putting it in a bag.\""), .direct("What was the phone worth?", "\"About three hundred dollars, and it had the patient's whole life on it, including photos and banking apps.\""), .direct("What did you do?", "\"When the patient came back and found it missing, I checked the video and called the sheriff's office.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} thought it was {D.his} own phone because it looked the same as the one {D.he} had.\""), .cross("Phones can look the same?", "\"Yes, many of them are identical in color and size, and cases are the main difference.\""), .cross("{DL} had a phone of {D.his} own?", "\"I think so, because a deputy found one in {D.his} jacket later.\""), .cross("{DL} didn't leave the clinic right away?", "\"No, {D.he} stayed another ten minutes and left only when called for {D.his} appointment.\""), .cross("The phone was returned?", "\"Yes, the deputy recovered it from {DL}'s bag.\""), .cross("The patient wasn't harmed?", "\"No, though {V.he} was upset about the phone being gone for an hour.\"")],
        theory: ("{D} took a phone again.", "A mix-up."),
        allocution: "\"I picked up that phone thinking it was mine, because I own the same model and set it down in the clinic waiting room. I realized my mistake after I got home. I'm sorry for the worry it caused the clinic and for not bringing it right back. I should have checked before I walked out.\"",
        truths: ("{DL} left through another door.", "{DL} owns the same model."),
        defendant: [.direct("Why did you pick up the phone?", "\"I thought it was mine. It was on the chair next to where I'd been sitting, and it looked just like my phone.\""), .direct("Did you check the screen?", "\"Not right away. I put it in my bag, and when my own phone buzzed later I realized I had two phones.\""), .direct("What did you do then?", "\"I took the extra phone out to give to the front desk, but I was called for my appointment before I could.\""), .direct("Did you mean to keep it?", "\"No. I'd never keep a phone that wasn't mine. I was going to turn it in as soon as I got out.\""), .direct("What did the deputy find?", "\"{OFF.He} found both phones in my bag and I explained what I thought had happened. I handed over the extra one.\""), .direct("What would you tell the patient?", "\"I'm sorry for the scare. I never meant to take your phone, and I'm glad it's back.\""), .cross("You were charged with taking a phone before, weren't you?", "\"Yes, and I know that casts doubt on what I'm saying. This time it was a mix-up.\""), .cross("You picked it up and put it in your bag without looking?", "\"I did, and that was careless. I should have checked first.\""), .cross("You didn't tell the front desk about the second phone?", "\"I meant to, and I was called back before I could. I should have told someone right away.\""), .cross("You'll check before picking up anything?", "\"Yes, I'll look at it first and ask the staff if it isn't mine.\""), .cross("You'll apologize to the patient?", "\"Yes, in person if the court allows it.\"")],
        openings: ("A patient left a phone on a chair beside the charging station of a clinic's waiting room while going back for an appointment, and the clinic camera shows {D} take it, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} thought the phone was {D.his} own, since the two look alike and sat beside the charging station. It was a mix-up, not a theft."),
