        defense: [E(.statement, 1, "Pay", "{DL} says it was owed pay.")],
        role: "Parent",
        exam: [.direct("What happened at your home?", "\"We hired {DL} as a babysitter for a few evenings, and after the third evening I found two hundred dollars missing from the kitchen drawer.\""), .direct("What was in the drawer?", "\"About two hundred dollars in cash that we keep for the cleaning service and small household errands, mostly in twenties.\""), .direct("How do you know it was taken that night?", "\"I'd counted it that morning, and the next morning the envelope was empty, with nobody else in the house but {DL}.\""), .direct("What does your kitchen camera show?", "\"It shows {DL} opening the drawer, taking out the envelope, counting some bills, and putting them into a pocket.\""), .direct("Why do you have a camera there?", "\"We installed it after a package theft, and we told {DL} when {D.he} started that cameras were running in common rooms.\""), .direct("What did {DL} say?", "\"{D.He} said we owed {D.him} pay from the earlier evenings and that {D.he} was only taking what was owed.\""), .cross("You hadn't paid {DL} for those nights yet?", "\"We usually pay at the end of the week, and the week wasn't over yet.\""), .cross("{DL} took exactly what you owed?", "\"No, {D.he} took the whole envelope, which was more than two evenings of pay.\""), .cross("{DL} left a note?", "\"No note, and {D.he} didn't text us about it either.\""), .cross("Your children were fine?", "\"Yes, they were in bed and nothing happened to them.\""), .cross("You have the camera video?", "\"Yes, I saved a copy and gave it to the deputy.\"")],
        theory: ("{D} took cash again.", "Owed pay."),
        allocution: "\"I took that money because I was owed pay, and I thought the family would understand. I never told them, and that was wrong. I should have asked at the end of the evening instead of reaching into a drawer. I'm sorry to the parents who let me watch their child, and I'll pay back every dollar.\"",
        truths: ("The camera shows three takings.", "Pay was current."),
        defendant: [.direct("Did you take the money?", "\"Yes, I took some of it. I'd been told I'd be paid at the end of the night, and the parents hadn't left any out.\""), .direct("Why did you open the drawer?", "\"I'd seen them take cash from it before, and I thought it was where they kept the money for the sitter.\""), .direct("How much did you take?", "\"I think I took about one hundred dollars, which was what I was owed for the first two nights.\""), .direct("Did you count the bills?", "\"Yes, I counted out what I thought I was owed, and I put the rest back in the envelope.\""), .direct("What did you tell the parents?", "\"I told them the next day that I'd taken my pay, and they said they hadn't agreed to it that way.\""), .direct("What would you tell the parents?", "\"I'm sorry for not asking first. I should have waited for you to pay me, and I'll repay anything over what I was owed.\""), .cross("You were told cameras were in the kitchen, weren't you?", "\"Yes, and I took the money anyway, which tells you I wasn't hiding anything. I still shouldn't have done it.\""), .cross("The envelope was empty the next morning?", "\"It was, and I don't know what happened to the rest. I only took what I thought was mine.\""), .cross("You've been accused of taking things from clients before?", "\"Yes, once, and that's why I should have been extra careful about pay.\""), .cross("You didn't text the parents first?", "\"No, and a text would have solved this. I should have sent one.\""), .cross("You'll repay the difference?", "\"Yes, whatever the court decides I took over what I earned.\"")],
